package org.brightstats.model;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.brightstats.stats.*;
/** Migration is checked against mathematical inputs, including deliberately nondefault masks and bounds. */
public final class DiagramTemplateChecks {
    private static int checks;
    private static void require(boolean condition,String message){checks++;if(!condition)throw new AssertionError(message);}
    private static double[] ram(SemModel.Model model){int size=model.variables().size();double[][] a=model.directed(),v=model.covariance();double[] means=model.intercepts();for(var parameter:model.parameters())for(var location:parameter.locations())switch(location.kind()){case DIRECTED->a[location.row()][location.column()]=parameter.start();case COVARIANCE->{v[location.row()][location.column()]=parameter.start();v[location.column()][location.row()]=parameter.start();}case INTERCEPT->means[location.row()]=parameter.start();}double[] result=new double[2*size*size+size];int next=0;for(var row:a)for(double value:row)result[next++]=value;for(var row:v)for(double value:row)result[next++]=value;for(double value:means)result[next++]=value;return result;}
    public static void main(String[] args)throws Exception{
        List<String> names=List.of("x1","x2","y1","y2");var blocks=List.of(new PlsSem.Block("X",new int[]{0,1},PlsSem.Mode.A),new PlsSem.Block("Y",new int[]{2,3},PlsSem.Mode.B));var edges=List.of(new PlsSem.Edge(0,1));var document=DiagramTemplates.pls(names,blocks,edges);var compiled=DiagramModels.pls(TypedDiagram.parse(document.json().toString()),names);require(compiled.edges().equals(edges),"PLS paths");for(int i=0;i<blocks.size();i++){var a=blocks.get(i);var b=compiled.blocks().get(i);require(a.name().equals(b.name())&&Arrays.equals(a.columns(),b.columns())&&a.mode()==b.mode()&&a.measurementType()==b.measurementType()&&Arrays.equals(a.initialWeights(),b.initialWeights()),"PLS block binding and options");}
        var base=Gsca.fromBlocks(names,blocks,edges).model();boolean[][] weights=base.weights(),loadings=base.loadings();double[][] initial=base.initialWeights();loadings[1][1]=true;weights[3][0]=true;initial[3][0]=.27;initial[0][0]=-.8;var model=new Gsca.Model(names,base.components(),weights,loadings,base.paths(),initial);var generalized=DiagramModels.gsca(DiagramTemplates.gsca(model),names).prepared();for(int row=0;row<generalized.columns().length;row++){int physical=generalized.columns()[row];for(int component=0;component<2;component++){require(generalized.model().weights()[row][component]==weights[physical][component],"GSCA weight mask");require(generalized.model().loadings()[row][component]==loadings[physical][component],"GSCA loading mask");require(generalized.model().initialWeights()[row][component]==initial[physical][component],"GSCA initial weight");}}
        double[][] data=new double[180][4];Random random=new Random(711);for(var row:data){double x=random.nextGaussian(),y=.4*x+random.nextGaussian();row[0]=x+.3*random.nextGaussian();row[1]=.8*x+.4*random.nextGaussian();row[2]=y+.3*random.nextGaussian();row[3]=.7*y+.4*random.nextGaussian();}var sem=SemModel.reflective(names,data,blocks.stream().map(block->new PlsSem.Block(block.name(),block.columns(),PlsSem.Mode.A)).toList(),edges,true,true).model();var semDiagram=DiagramTemplates.sem(sem,true);var preserved=new TypedDiagramHistory(semDiagram);preserved.record(semDiagram.move(Set.of(semDiagram.nodes().get(1).id()),20,10));require(preserved.undo().equals(semDiagram),"SEM bounds survive typed JSON history");var restored=DiagramSem.compile(semDiagram,names,data,true).prepared();double[] expectedRam=ram(sem),actualRam=ram(restored.model());require(expectedRam.length==actualRam.length,"SEM RAM dimensions");for(int index=0;index<expectedRam.length;index++)require(expectedRam[index]==actualRam[index],"SEM RAM initial moments");for(var parameter:sem.parameters())for(var location:parameter.locations()){var equivalent=restored.model().parameters().stream().filter(candidate->candidate.locations().contains(location)).findFirst().orElseThrow();require(Objects.equals(parameter.lower(),equivalent.lower())&&Objects.equals(parameter.upper(),equivalent.upper())&&parameter.scale()==equivalent.scale(),"SEM bounds and scale migration");}
        for(boolean intercept:new boolean[]{true,false}){var regression=DiagramModels.regression(DiagramTemplates.regression(names,3,new int[]{0,1},intercept),names);require(regression.intercept()==intercept&&Arrays.equals(regression.predictors(),new int[]{0,1})&&regression.response()==3,"Regression intercept and roles");}
        var process=new PathProcess.Model(0,3,List.of(new PathProcess.Path(0,3,new int[]{1})),new int[]{2});var processDiagram=DiagramTemplates.process(names,process);var derived=DiagramProcess.compile(processDiagram,names,data);require(derived.extensions().size()==1,"PROCESS moderation survives migration");require(derived.composites().size()==4,"PROCESS single-indicator composites");
        Path out=Path.of(args[0]);Files.createDirectories(out);var gson=new GsonBuilder().setPrettyPrinting().create();for(var entry:Map.of("pls",document,"gsca",DiagramTemplates.gsca(model),"sem",semDiagram,"process",processDiagram,"regression",DiagramTemplates.regression(names,3,new int[]{0,1},false)).entrySet())Files.writeString(out.resolve("template-"+entry.getKey()+".json"),gson.toJson(entry.getValue()));System.out.println("{\"checks\":"+checks+",\"families\":5}");
    }
}
